      "exceptions":[],
      "grounding":[
        {
          "end_line":730,
          "quote":"Where a public carrier refines into inner executable structure, publish the live traversal boundaries explicitly through lawful GTL boundary surfaces such as `RefinementBoundary` or `CandidateFamily`.\n\nThe outer public carrier remains the callable contract.",
          "section_id":"repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/ODD_METHOD.md#ODD%20Method%2F11.%20Core%20Law%2F11.4%20The%20GTL%20Module%20Is%20The%20Operative%20Publication%20Surface",
          "start_line":728
